let _EMO = null;
function emoData() {
  if (_EMO) return _EMO;
  _EMO = EMO_RAW.split('\n').map(l => { const p = l.split('\t'); return { n: p[0], items: p.slice(1).map(x => { const i = x.indexOf(' '); return { e: x.slice(0, i), k: x.slice(i + 1) }; }) }; });
  return _EMO;
}
const EMO_TAB = ['😀', '👋', '🐶', '🍕', '✈️', '⚽', '💡', '❤️', '🏁'];
const firstEmoji = s => { s = String(s || '').trim(); if (!s) return ''; try { const seg = new Intl.Segmenter('fr', { granularity: 'grapheme' }); for (const g of seg.segment(s)) { if (/\p{Extended_Pictographic}|\p{Regional_Indicator}/u.test(g.segment)) return g.segment; } } catch (e) { const m = s.match(/\p{Extended_Pictographic}\uFE0F?/u); if (m) return m[0]; } return ''; };
const empGrid = (list, cur) => list.map(x => `<button type="button" data-pick="icon" data-val="${esc(x)}" class="${x === cur ? 'on' : ''}">${x}</button>`).join('');
function emojiPicker(cur, sugg) {
  const d = emoData();
  F._sugg = sugg;
  return `<div class="emp"><div class="emp-top"><span class="emp-cur" id="emp-cur">${esc(cur)}</span><input class="inp" id="emp-q" placeholder="Chercher (pizza, plage, vélo…) ou colle un émoji" autocomplete="off" enterkeyhint="search"></div>
    <div class="emp-tabs"><button type="button" class="on" data-act="emp-cat" data-i="-1" aria-label="Suggestions">⭐</button>${d.map((g, i) => `<button type="button" data-act="emp-cat" data-i="${i}" aria-label="${esc(g.n)}">${EMO_TAB[i] || '•'}</button>`).join('')}</div>
    <div class="emojis emp-grid" id="emp-grid">${empGrid(sugg, cur)}</div></div>`;
}
ACT['emp-cat'] = d => {
  const i = parseInt(d.i, 10), g = document.getElementById('emp-grid'); if (!g) return;
  $$('.emp-tabs button').forEach(b => b.classList.toggle('on', b.dataset.i === String(i)));
  const q = document.getElementById('emp-q'); if (q) q.value = '';
  g.innerHTML = empGrid(i < 0 ? (F._sugg || []) : emoData()[i].items.map(x => x.e), F.icon); g.scrollTop = 0;
};
function empSearch(v) {
  const g = document.getElementById('emp-grid'); if (!g) return;
  const em = firstEmoji(v);
  if (em && !/[a-zA-Z]/.test(v)) { F.icon = em; const c = document.getElementById('emp-cur'); if (c) c.textContent = em; g.innerHTML = empGrid([em], em); return; }
  const toks = norm(v).split(/\s+/).filter(Boolean);
  if (!toks.length) { ACT['emp-cat']({ i: -1 }); return; }
  $$('.emp-tabs button').forEach(b => b.classList.remove('on'));
  const res = []; emoData().forEach(gr => gr.items.forEach(x => { if (res.length < 160 && toks.every(t => x.k.includes(t))) res.push(x.e); }));
  g.innerHTML = res.length ? empGrid(res, F.icon) : '<p class="mut sm" style="grid-column:1/-1;padding:10px 4px">Aucun émoji trouvé. Tu peux aussi en coller un dans la case.</p>';
}
